mapper.update:
UPDATE alarm_incident
SET status = #{status}, assignee = #{assignee}, acknowledged_at = #{acknowledgedAt},
    resolved_at = #{resolvedAt}, ended_at = #{endedAt}, updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE alarm_incident
SET escalation_candidate = #{candidate}, escalation_evaluated_at = #{evaluatedAt},
    updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT id, status, severity, service_code, environment, correlation_basis, summary, started_at, ended_at,
       escalation_candidate, escalation_evaluated_at, assignee, acknowledged_at, resolved_at,
       created_at, updated_at
FROM alarm_incident

    AND status = #{status}
    AND severity = #{severity}
    AND service_code = #{serviceCode}
    AND started_at >= #{fromTime}
    AND started_at <= #{toTime}
    AND id < #{cursorId}

ORDER BY id DESC
LIMIT #{limit}
